# test.advisortool.app goes up. Run from the project folder:  bash scripts/cloudflare-setup.sh
# Nothing here deploys; the agent deploys after. The live site stays on Vercel throughout.

cd "$(dirname "$0")/.."
export NO_PROXY='*' no_proxy='*'   # the Mac's system proxy points at a dead port
WORKER=advisortool
wr() { npx --yes wrangler "$@"; }

# put_secret NAME VALUE: one secret on the Worker, its value never printed
put_secret() {
  if printf '%s' "$2" | wr secret put "$1" --name "$WORKER" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$1"); printf '  %s✓ เก็บแล้ว%s %s\n' "$GREEN" "$RESET" "$1"
  else
    SKIPPED+=("$1 (เก็บไม่สำเร็จ ลองใหม่ด้วย: npx wrangler secret put $1 --name $WORKER)"); warn "เก็บ $1 ไม่สำเร็จ"
  fi
}

TOTAL_STAGES=7

