import json, sys
out, keys = sys.argv[1], sys.argv[2:]
vals = {}
for line in open(".env.local", encoding="utf-8"):
    line = line.strip()
    if not line or line.startswith("#") or "=" not in line: continue
    k, v = line.split("=", 1)
    v = v.strip()
    if len(v) >= 2 and v[0] == v[-1] and v[0] in "'\"": v = v[1:-1]
    if k.strip() in keys: vals[k.strip()] = v
json.dump(vals, open(out, "w"))
print(f"  พบ {len(vals)} จาก {len(keys)} ตัว")
PY
  if wr secret bulk "$BULK" --name "$WORKER"; then
